673	std::vector<Node> LiaStarExtension::getStarConstraints(Node n)
674	{
675	  // Lazy path: return the star constraints over all cones accumulated so far in
676	  // `d_lazyCones[n[0]]`. The per-cone constraints (and their fresh skolems) are
677	  // computed only once per cone and cached in `d_starConstraints`/`d_lambdas`
678	  // (so the skolems are stable across refinement rounds); only the sum
679	  // constraints, which span all cones, are rebuilt on each call.
680	  std::vector<Node> vec(n.begin() + 1, n.end());
681	  size_t dimension = vec.size();
682	
683	  // the cones accumulated so far for this lambda (n[0])
684	  std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& cones =
685	      d_lazyCones[n[0]];
686	
687	  // The per-cone constraints and lambdas computed in previous calls. We only
688	  // compute new constraints (and fresh skolems) for cones that have not been
689	  // processed yet, and append them here.
690	  std::vector<Node>& starConstraints = d_starConstraints[n[0]];
691	  std::vector<std::pair<Vector, std::vector<Vector>>>& lambdas =
692	      d_lambdas[n[0]];
693	  size_t& processed = d_processedCones[n[0]];
694	
695	  for (; processed < cones.size(); processed++)
696	  {
697	    Cone<Integer>& cone = cones[processed].second;
698	    for (const auto& generator : getConeGenerators(cone, dimension))
699	    {
700	      Trace("liastar-ext") << toString(generator) << std::endl;
701	      // Build the generator's star encoding directly over skolems: the star
702	      // constraints are asserted at the top level (not under a quantifier).
703	      std::vector<Node> vars, constraints;
704	      Vector point;
705	      std::vector<Vector> rays;
706	      LiaStarUtils::getGeneratorBody(dimension,
707	                                     generator,
708	                                     cone.getHilbertBasis(),
709	                                     /*star=*/true,
710	                                     /*useSkolems=*/true,
711	                                     d_nm,
712	                                     vars,
713	                                     constraints,
714	                                     point,
715	                                     rays);
716	      starConstraints.insert(
717	          starConstraints.end(), constraints.begin(), constraints.end());
718	      lambdas.push_back({point, rays});
719	    }
720	  }
721	
722	  // The sum constraints span the lambdas of all cones, so they are rebuilt from
723	  // the accumulated lambdas on each call. Start from the persisted per-cone
724	  // constraints and append the freshly built sum constraints, leaving
725	  // `d_starConstraints` holding only the per-cone constraints.
726	  std::vector<Node> result = starConstraints;
727	  std::vector<Node> sums = buildSumConstraints(d_nm, d_zero, vec, lambdas);
728	  result.insert(result.end(), sums.begin(), sums.end());
729	
730	  return result;
731	}
