128	 *     vec[i] = sum over all generators of (point[i] + sum over rays of ray[i]).
129	 * `lambdas` holds one (point, rays) contribution per module generator across
130	 * all cones (as produced by `LiaStarUtils::getGeneratorBody`); `vec` is the
131	 * star vector (the v_1 ... v_n). Returns the n equalities.
132	 */
133	std::vector<Node> buildSumConstraints(
134	    NodeManager* nm,
135	    Node zero,
136	    const std::vector<Node>& vec,
137	    const std::vector<std::pair<Vector, std::vector<Vector>>>& lambdas)
138	{
139	  size_t dimension = vec.size();
140	  Vector sums(dimension, zero);
141	  for (const std::pair<Vector, std::vector<Vector>>& lambda : lambdas)
142	  {
143	    for (size_t i = 0; i < dimension; i++)
144	    {
145	      sums[i] = nm->mkNode(Kind::ADD, sums[i], lambda.first[i]);
146	      for (const Vector& ray : lambda.second)
147	      {
148	        sums[i] = nm->mkNode(Kind::ADD, sums[i], ray[i]);
149	      }
150	    }
151	  }
152	  std::vector<Node> result;
153	  for (size_t i = 0; i < dimension; i++)
154	  {
155	    result.push_back(vec[i].eqNode(sums[i]));
156	  }
157	  return result;
158	}
