160	/**
161	 * Trace the cone's Hilbert basis and return its module generators -- the base
162	 * lattice points g of the decomposition { g + sum_j l_j h_j } of the cone's
163	 * integer points. A purely homogeneous cone has no module generators; its
164	 * single base point is then the origin, so the zero vector is returned
165	 * instead.
166	 */
167	std::vector<std::vector<Integer>> getConeGenerators(
168	    libnormaliz::Cone<Integer>& cone, size_t dimension)
169	{
170	  Trace("liastar-ext") << "Hilbert basis:" << std::endl;
171	  for (const auto& basis : cone.getHilbertBasis())
172	  {
173	    Trace("liastar-ext") << toString(basis) << std::endl;
174	  }
175	  Trace("liastar-ext") << "Module generators:" << std::endl;
176	  if (!cone.getModuleGenerators().empty())
177	  {
178	    return cone.getModuleGenerators();
179	  }
